'''Render state-based task designs with implementation evidence. No simulation side effects.'''
import html
import json

def h(value):
    return html.escape(str(value), quote=True)

def items(values):
    return '<ul>'+''.join('<li>'+h(v)+'</li>' for v in values)+'</ul>'

def render_success_rules(p):
    key=p['benchmark']+'--'+p['task']; result=[]
    labels={'final':'最终状态','hold':'连续保持','always':'全程状态'}
    for c in p['state_checks']:
        time=('最后 '+str(c['seconds'])+' 秒') if c['operator']=='hold' else c['window'] if c['operator']=='always' else '评测结束时'
        result.append('<li class="state-check"><span class="rule-tag">'+labels[c['operator']]+' · '+h(time)+'</span><p><b>'+h(c['predicate'])+'</b></p><code>'+h(c['expression'])+'</code></li>')
    return '<ol class="state-check-list">'+''.join(result)+'</ol>'

def render_evidence(p):
    key=p['benchmark']+'--'+p['task']; result=[]
    for a in p['success_rule_audit']:
        back='、'.join('<a href="#origin-'+h(key)+'-'+h(i)+'">'+h(i)+'</a>' for i in a['original_mapping_ids']) or 'World新增状态'
        sources=''.join('<details class="rule-source"><summary>'+h(s['path'].split('/')[-1])+':'+str(s['line'])+'–'+str(s['end_line'])+'</summary><p><a href="'+h(s['path'])+'">完整源文件</a></p><pre>'+h(s['excerpt'])+'</pre></details>' for s in a['sources'])
        result.append('<li class="success-rule" id="rule-'+h(key)+'-'+str(a['rule_index'])+'"><b>S'+str(a['rule_index']).zfill(2)+' · '+h(a['rule'])+'</b><p>'+h(a['original_basis'])+'</p><p class="small">原判定映射：'+back+'</p>'+sources+'</li>')
    return '<details class="nested evidence-panel"><summary>状态依据与源码（沿用 / World新增）</summary><p class="small">原状态或奖励有依据，不代表新增容差和时长已经验证；所有新阈值仍需校准。</p><ol>'+''.join(result)+'</ol></details>'

def render_mapping(p):
    key=p['benchmark']+'--'+p['task']; rows=[]
    for o in p['original_judgement_mapping']:
        targets='、'.join('<a href="#rule-'+h(key)+'-'+str(i)+'">S'+str(i).zfill(2)+'</a>' for i in o['maps_to_success_rules'])
        rows.append('<tr id="origin-'+h(key)+'-'+h(o['id'])+'"><th scope="row">'+h(o['id'])+' '+h(o['name'])+'</th><td data-label="原判定">'+h(o['expression'])+'</td><td data-label="现在放在哪里"><b>'+h(o['destination'])+'</b> '+targets+'<p>'+h(o['handling'])+'</p></td></tr>')
    return '<details class="nested origin-mapping"><summary>原判定 → 环境设置 / 状态检查的映射</summary><table class="goal-table"><thead><tr><th>原项目</th><th>原逻辑</th><th>本版对应位置</th></tr></thead><tbody>'+''.join(rows)+'</tbody></table><p class="small">原连续指标继续单独报告：'+h(p['two_layer_review']['metric_preservation'])+'</p></details>'

def render_prompts(p):
    q=p['prompt_comparison']; extra=''
    if q['developer_before']:
        extra+='<h5>历史 developerInstructions</h5><pre>'+h(q['developer_before'])+'</pre>'
    if q['tools_before']:
        extra+='<details class="nested"><summary>历史完整工具schema</summary><pre>'+h(json.dumps(q['tools_before'],ensure_ascii=False,indent=2))+'</pre></details>'
    return '<details class="nested prompt-comparison"><summary>英文prompt对照（历史原文 / 当前World v1）</summary><p class="small">'+h(q['after_scope'])+'</p><div class="prompt-columns"><section><h4>'+h(q['before_kind'])+'</h4><a href="'+h(q['before_source'])+'">原文件</a><pre>'+h(q['before'])+'</pre>'+extra+'</section><section><h4>当前英文任务附加段 · World v1已启用</h4><pre>'+h(q['after_task_draft'])+'</pre><a href="'+h(q['action_contract_source'])+'">沿用的英文动作接口说明</a></section></div></details>'

def render_proposals(data, rows, benches):
    baseline={(r['benchmark'],r['task']):r for r in rows};cards=[]
    count=sum(len(p['state_checks']) for p in data['proposals']); total=len(data['proposals']); task_count=len(rows)
    for p in data['proposals']:
        key=p['benchmark']+'--'+p['task'];r=baseline[p['benchmark'],p['task']];e=p['environment_settings']
        search=' '.join([p['title'],p['ability'],p['benchmark'],p['task'],r['title_zh'],str(r.get('legacy_task_id') or '')]).lower()
        audit=render_evidence(p)+render_mapping(p)+render_prompts(p)
        v=p.get('implementation',{})
        validation='<p class="proposal-before"><b>实现验证：</b>构造状态正反例通过；Docker状态读取通过（'+str(v.get('diagnostic_steps','?'))+'步诊断）。<b>尚无该题物理成功轨迹证明。</b> <a href="'+h(v.get('evidence',''))+'">原始判定记录</a> · <a href="reports/validation/world-success-v1/README.md">验证报告及视频</a></p>'
        cards.append(f'''<details class="proposal" id="proposal-{h(key)}" data-key="{h(key)}" data-scope="{p['group']}" data-search="{h(search)}" data-decision="accept" data-design-approved="true">
<summary><div><span class="task-id">{h(benches[p['benchmark']])} / {h(p['task'])}</span><h3>{h(p['title'])}</h3></div><div class="summary-meta"><span class="tag">{len(p['state_checks'])}条状态检查</span><span class="review-state">设计已认可</span><span class="chevron">＋</span></div></summary>
<div class="proposal-body">{validation}<div class="goal-brief"><p><b>原场景：</b>{h(p['original_task']['goal'])}</p><p><b>新场景：</b>{h(p['scene'])}</p></div>
<div class="simple-layout"><section class="environment-settings"><h4>环境设置</h4>{items(e['items'])}<p class="budget-line"><b>预算：</b>{e['step_limit']}步 / {e['control_hz']}Hz ≈ {e['duration_s']:.3g}s。<br><b>结束：</b>{h(e['evaluation_end'])}。</p></section>
<section class="success-summary"><h4>成功判定 · 以下状态全部满足</h4>{render_success_rules(p)}</section></div>
<details class="nested state-definitions"><summary>状态怎么计算？</summary>{items(e['state_definitions'])}<p class="small">过程状态只由评测端真实轨迹累计，不额外发给模型；保持时间使用模拟时间。</p></details>
<p class="simplification"><b>这次简化：</b>{h(p['simplification'])}</p>
<details class="audit-fold"><summary>展开原判定映射、源码依据与prompt对照</summary>{audit}<p class="small">{h(p['risk'])}</p><a href="#task-{h(p['benchmark'])}-{h(p['task'])}">查看原生评分卡片（保留作对照）</a></details>
<div class="review-controls"><label for="decision-{h(key)}">审核意见<select class="review-decision" id="decision-{h(key)}"><option value="pending">待审核</option><option value="accept">原则认可，仍需校准</option><option value="revise">需要调整</option><option value="defer">暂不改造</option></select></label><label for="note-{h(key)}">修改建议<textarea class="review-note" id="note-{h(key)}" rows="2" placeholder="例如：只看最后3秒；调整环境扰动强度"></textarea></label></div></div></details>''')
    protocol=data['common_protocol']
    common=''.join('<li>'+h(protocol[k])+'</li>' for k in ['endpoint','validity','process','sampling','provenance'])
    return f'''<section class="section proposal-section" id="proposals"><div class="proposal-heading"><div><span class="eyebrow">STATE CHECKS / WORLD STATE V1</span><h2>环境负责出题，success只检查状态</h2></div><span class="tag proposal-tag">已实现 · 接线已验证 · 可行性待校准</span></div>
<p class="lead">{total}个场景，{count}条状态检查。每题1～2条；力、时刻、场地和预算归环境设置。原生失败单独保留，原连续分继续报告。</p>
<div class="proposal-principles"><article><h3>最终状态 · final</h3><p>结束时是否完成。例如路线已走完、达标击球数≥4。</p></article><article><h3>连续保持 · hold</h3><p>最后N秒一直满足。例如最后2秒在目标区停稳；中途违例不能拼接好帧。</p></article><article><h3>全程状态 · always</h3><p>指定窗口内一直满足。例如运输全程不掉物、完整轨迹窗口内跟踪达标。</p></article></div>
<p class="proposal-before"><b>统一裁定：</b>{h(protocol['decision'])}<br><span class="small">过程要求保留为轨迹状态；只看最后一帧无法证明之前有没有掉物、跳跃或完成路线。</span></p>
<details class="proposal-protocol"><summary>统一执行约定与统计方式</summary><ul>{common}<li>接触异常退让题已按用户要求移除，不进入当前题集与总成功率。</li><li>World SR按有效回合的布尔结果统计；来源无官方SR时仍称World SR。checker已接入；本次没有运行GPT评测，诊断不计模型SR。</li></ul></details>
<div class="toolbar proposal-toolbar"><input id="proposal-search" type="search" placeholder="搜索场景、benchmark…" aria-label="搜索提案"><select id="proposal-scope" aria-label="范围"><option value="">全部{total}项</option><option value="main">连续分任务14项</option><option value="optional">统计调整{data['optional_count']}项</option></select><select id="proposal-decision" aria-label="审核状态"><option value="">全部审核状态</option><option value="pending">待审核</option><option value="accept">原则认可</option><option value="revise">需要调整</option><option value="defer">暂不改造</option></select><button id="proposal-expand">展开当前场景</button><button id="proposal-collapse">收起场景</button></div>
<div class="result-bar"><span id="proposal-count" aria-live="polite"></span><button id="review-export">导出审核意见</button></div><p class="small muted" id="review-storage-status">已按本次指令记录设计认可；下方可继续标注修订意见。checker已实现；状态测试通过不等于已获得物理成功轨迹。</p>
<div id="proposal-list">{''.join(cards)}</div><p id="proposal-empty" hidden>没有匹配的场景。</p><p class="small muted"><a href="docs/scoring/success-proposals.json">当前设计数据</a> · <a href="docs/scoring/archive/scoring-guide-v0.1.html#proposals">旧版详细提案（归档，不再生效）</a>。下面保留活动题集{task_count}题的原生评分卡片作对照。</p></section>'''

CSS='\n.dual-review{margin:26px 0}.origin-mapping>summary{cursor:pointer;font-weight:650;color:var(--teal)}.success-rule,.origin-mapping tr{scroll-margin-top:100px}\n.success-rule-list{padding-left:24px}.success-rule{padding:17px 0;border-bottom:1px solid #bdd2c6}.success-rule:last-child{border-bottom:0}.success-rule p{margin:9px 0}.rule-tag{display:inline-block;padding:3px 8px;font-size:12px;border-radius:5px;background:#fff1dc;color:#795018;border:1px solid #e0c899}.success-rule[data-provenance="native"] .rule-tag{background:#e0f0e7;color:#155b45;border-color:#9bbda9}.rule-source{font-size:13px;margin:7px 0}.rule-source summary{cursor:pointer;color:var(--teal);overflow-wrap:anywhere}.rule-source pre{font:12px/1.65 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#fff;padding:12px;border:1px solid var(--line);max-height:350px;overflow:auto}\n.goal-comparison{margin:0 0 25px}.original-goal{font-size:18px;font-weight:600}.change-scope{padding:15px 18px;background:#eaf3ef;border-left:3px solid var(--teal)}.goal-table{table-layout:fixed;margin:18px 0;overflow-wrap:anywhere}.goal-table caption{text-align:left;font-weight:700;padding:10px 0}.goal-table th:first-child{width:16%}.goal-table td{width:42%}.goal-table tbody th{background:#f5f8f6}.threshold-evidence{padding:18px 20px;margin:24px 0;background:#fff7e9;border:1px solid #ead7b5;border-radius:9px}.threshold-evidence ul{padding-left:20px}.threshold-evidence li{margin:12px 0}.threshold-evidence li p{margin:5px 0;font-size:14px}.prompt-comparison{margin:24px 0 30px}.prompt-comparison>summary{font-size:16px;font-weight:650}.prompt-columns{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px;margin-top:18px}.prompt-columns section{min-width:0}.prompt-columns pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f2f5f3;padding:15px;border:1px solid var(--line);border-radius:8px;font:12px/1.75 ui-monospace,monospace;max-height:640px;overflow:auto}.prompt-columns h5{margin-bottom:6px}.goal-comparison code{overflow-wrap:anywhere}@media(max-width:800px){.prompt-columns{grid-template-columns:1fr}.goal-table,.goal-table tbody,.goal-table tr,.goal-table td,.goal-table th{display:block;width:100%!important}.goal-table thead{display:none}.goal-table td::before{content:attr(data-label);display:block;font-weight:700;color:var(--teal);margin-bottom:5px}.goal-table tbody th{border-top:2px solid var(--line)}.goal-table td{padding:12px}.threshold-evidence{padding:14px}.original-goal{font-size:16px}}@media print{.prompt-columns pre{max-height:none;overflow:visible}}\n.proposal-nav{display:flex;flex-wrap:wrap;gap:12px;margin:20px 0}.proposal-nav a{padding:10px 16px;background:var(--pale);border:1px solid var(--line);border-radius:8px;text-decoration:none;font-weight:650}.proposal-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.proposal-heading h2{margin-top:8px}.proposal-tag{background:#fff0d9;color:#815013}.proposal-principles{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:24px 0}.proposal-principles article{background:var(--white);border:1px solid var(--line);border-top:3px solid var(--teal);border-radius:10px;padding:20px}.proposal-principles p{font-size:15px}.proposal-protocol{background:var(--pale);border:1px solid var(--line);padding:16px 20px;border-radius:10px;margin-bottom:24px}.proposal-protocol summary{cursor:pointer;font-weight:700}.proposal-protocol li{padding:4px 0}.proposal{background:white;border:1px solid var(--line);border-radius:12px;margin:14px 0;overflow:hidden;scroll-margin-top:20px}.proposal>summary{display:flex;justify-content:space-between;gap:20px;align-items:center;padding:20px 24px;cursor:pointer;list-style:none}.proposal>summary::-webkit-details-marker{display:none}.proposal[open]>summary{border-bottom:1px solid var(--line);background:#f1f7f4}.proposal[open] .chevron{transform:rotate(45deg)}.proposal-body{padding:24px}.proposal-before{border-left:3px solid #adbcb5;background:#f6f8f6;padding:12px 16px;margin-bottom:24px;font-size:14px}.proposal-fields{display:grid;grid-template-columns:1fr 1fr;gap:24px}.proposal-field{min-width:0}.proposal-field h4{font-size:16px}.proposal-field ul{padding-left:21px;margin:0}.proposal-field li{margin-bottom:9px}.success-field{grid-column:1/-1;padding:20px;background:#edf7f2;border:1px solid #bfd6cb;border-radius:9px}.proposal-risk{margin:24px 0;padding:16px 20px;background:var(--amber);border-radius:9px}.proposal-risk p{margin:7px 0 0}.review-controls{display:grid;grid-template-columns:260px 1fr;gap:20px;border-top:1px solid var(--line);padding-top:18px}.review-controls label{display:flex;flex-direction:column;gap:7px;font-size:14px;font-weight:600}.review-controls select,.review-controls textarea{width:100%;font:inherit;line-height:1.6;padding:9px 12px;border:1px solid #a8bdb4;border-radius:7px;background:white;color:var(--ink)}.review-controls textarea{resize:vertical}.review-state{font-size:13px;color:var(--muted)}.proposal[data-decision="accept"]{border-color:#298069}.proposal[data-decision="revise"]{border-color:#b07928}.proposal[data-decision="defer"]{border-color:#a2a9ad}.proposal-toolbar{margin-top:24px}.proposal-section{border-top:2px solid var(--teal);padding-top:30px}.proposal-jump{margin:0 0 16px;padding:10px 14px;background:var(--amber);border-radius:7px;font-size:14px}\n@media(max-width:800px){.proposal-principles,.proposal-fields,.review-controls{grid-template-columns:1fr}.proposal-heading{align-items:flex-start;flex-direction:column;gap:4px}.proposal>summary{align-items:flex-start;flex-direction:column;padding:17px}.proposal>summary .summary-meta{align-items:flex-start}.proposal-body{padding:17px}.proposal-heading h2{font-size:25px}.proposal-toolbar{grid-template-columns:1fr}.success-field{padding:15px}.proposal-nav a{flex:1;text-align:center}.proposal-protocol{padding:13px}.proposal-protocol ol{padding-left:24px}.proposal-tag{white-space:normal}}\n@media print{.review-controls,.proposal-toolbar,#review-export{display:none}.proposal-body{display:block}.proposal{break-inside:avoid}}\n\n.simple-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.1fr);gap:24px;margin:20px 0}.environment-settings,.success-summary{padding:20px;border:1px solid var(--line);border-radius:10px}.success-summary{background:#edf7f2;border-color:#b4d3c4}.environment-settings ul{padding-left:20px;margin:0}.environment-settings li{margin:10px 0}.budget-line{padding-top:13px;border-top:1px solid var(--line);font-size:14px}.state-check-list{padding-left:23px;margin:0}.state-check{padding:12px 0;border-bottom:1px solid #c5d9cf}.state-check:last-child{border-bottom:0}.state-check p{margin:8px 0}.state-check code{display:block;overflow-wrap:anywhere;color:#3b6054;font-size:12px}.goal-brief{border-left:3px solid var(--teal);padding:10px 16px;background:#f5f8f6}.goal-brief p:last-child{margin-bottom:0}.simplification{font-size:14px;color:var(--muted);margin:18px 0}.audit-fold{border:1px solid var(--line);padding:14px;border-radius:8px;margin-bottom:20px}.audit-fold>summary{cursor:pointer;color:var(--teal);font-size:14px;font-weight:650}.state-definitions ul{padding-left:20px}.state-definitions li{margin:10px 0}.audit-fold .prompt-comparison{margin:0}.success-rule pre{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:800px){.simple-layout{grid-template-columns:1fr;gap:14px}.environment-settings,.success-summary{padding:15px}.audit-fold{padding:12px}}\n'

JS='\nconst proposalCards=[...document.querySelectorAll(\'.proposal\')];\nconst reviewKey=\'robotworld-success-proposals-v0.3-review\',reviewLabels={pending:\'待审核\',accept:\'设计已认可\',revise:\'需要调整\',defer:\'暂不改造\'};\nlet reviewState={};try{reviewState=JSON.parse(localStorage.getItem(reviewKey)||\'{}\')||{}}catch(e){$(\'review-storage-status\').textContent=\'此浏览器不能保存本地标注，请在离开页面前导出审核意见。\'}\nfunction proposalFilter(){let n=0;const q=$(\'proposal-search\').value.trim().toLowerCase(),s=$(\'proposal-scope\').value,d=$(\'proposal-decision\').value;for(const c of proposalCards){c.hidden=!!((q&&!c.dataset.search.includes(q))||(s&&c.dataset.scope!==s)||(d&&c.dataset.decision!==d));if(!c.hidden)n++}const reviewed=proposalCards.filter(c=>c.dataset.decision!==\'pending\').length;$(\'proposal-count\').textContent=`显示 ${n} / ${proposalCards.length} 项 · 已标注 ${reviewed} 项`;$(\'proposal-empty\').hidden=n!==0;document.body.dataset.visibleProposals=n}\nfunction persistReview(){try{localStorage.setItem(reviewKey,JSON.stringify(reviewState))}catch(e){$(\'review-storage-status\').textContent=\'本地保存不可用，请导出审核意见后再关闭页面。\'}}\nfor(const c of proposalCards){const select=c.querySelector(\'.review-decision\'),note=c.querySelector(\'.review-note\'),saved=reviewState[c.dataset.key]||{};select.value=Object.hasOwn(reviewLabels,saved.decision)?saved.decision:(c.dataset.designApproved===\'true\'?\'accept\':\'pending\');note.value=typeof saved.note===\'string\'?saved.note:\'\';const update=save=>{c.dataset.decision=select.value;c.querySelector(\'.review-state\').textContent=reviewLabels[select.value];if(save){reviewState[c.dataset.key]={decision:select.value,note:note.value};persistReview()}proposalFilter()};select.onchange=()=>update(true);note.oninput=()=>update(true);update(false)}\nfor(const id of [\'proposal-search\',\'proposal-scope\',\'proposal-decision\']){$(id).oninput=proposalFilter;$(id).onchange=proposalFilter}\n$(\'proposal-expand\').onclick=()=>proposalCards.filter(c=>!c.hidden).forEach(c=>c.open=true);$(\'proposal-collapse\').onclick=()=>proposalCards.forEach(c=>c.open=false);\n$(\'review-export\').onclick=()=>{const payload={proposal_version:\'world-success-proposals-v0.3\',status:\'review_notes_only_not_execution_approval\',exported_at:new Date().toISOString(),reviews:proposalCards.map(c=>({task:c.dataset.key,decision:c.querySelector(\'.review-decision\').value,note:c.querySelector(\'.review-note\').value}))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:\'application/json\'});const url=URL.createObjectURL(blob),a=document.createElement(\'a\');a.href=url;a.download=\'robotworld-success-proposal-review-v0.3.json\';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)};\nfunction openScoringAnchor(){const id=decodeURIComponent(location.hash.slice(1)),target=document.getElementById(id);if(!target)return;if(id.startsWith("rule-")||id.startsWith("origin-")){for(const f of ["proposal-search","proposal-scope","proposal-decision"])$(f).value="";proposalFilter();let node=target;while(node){if(node.tagName==="DETAILS")node.open=true;node=node.parentElement}target.scrollIntoView();return;}if(target.classList.contains(\'proposal\')){for(const f of [\'proposal-search\',\'proposal-scope\',\'proposal-decision\'])$(f).value=\'\';proposalFilter();target.open=true}else if(target.classList.contains(\'task\')){$(\'reset\').click();target.open=true}if(id.startsWith(\'proposal-\')||id.startsWith(\'task-\'))target.scrollIntoView()}\nwindow.addEventListener(\'hashchange\',openScoringAnchor);proposalFilter();openScoringAnchor();document.body.dataset.proposalsReady=\'true\';\n'
